// The parts of views.sql the access tests expect, whole (spec/behaviour.md, "Access").
import { generate } from "./project.js";

/** views.sql's start, up to the first view. */
export const header = [
  "-- Generated by Ingestron for erp: Synapse serverless SQL views. Do not edit.",
  "-- It switches to each view's database and creates or alters each view, so it can run again.",
  "",
  "USE [erp_dev];",
  "GO",
  "",
  "",
].join("\n");

/** The orders view over its landed files. */
export const ordersView = [
  "IF SCHEMA_ID(N'bronze') IS NULL EXEC(N'CREATE SCHEMA [bronze]');",
  "GO",
  "CREATE OR ALTER VIEW [bronze].[orders] AS",
  "SELECT *",
  "FROM OPENROWSET(",
  "  BULK 'erp/orders/orders.parquet',",
  "  DATA_SOURCE = 'landing',",
  "  FORMAT = 'PARQUET'",
  ") WITH (",
  "  [id] BIGINT,",
  "  [total] FLOAT,",
  "  [email] VARCHAR(8000) COLLATE Latin1_General_100_BIN2_UTF8",
  ") AS [rows];",
  "GO",
  "",
].join("\n");

/** The grants on [bronze].[orders] in the access project. */
export const grants = [
  "GRANT SELECT ON OBJECT::[bronze].[orders] TO [marketing-analysts-dev];",
  "GRANT SELECT ON OBJECT::[bronze].[orders] TO [etl-writers];",
  "GRANT SELECT ON OBJECT::[bronze].[orders] TO [ops]]admins];",
  "GO",
  "",
].join("\n");

/** The exact grants batch of [bronze].[orders], keeping SELECT for `kept`. */
export function revokes(kept?: string): string {
  return [
    "DECLARE @revoke NVARCHAR(MAX);",
    "SELECT @revoke = STRING_AGG(CONVERT(NVARCHAR(MAX), N'REVOKE ' + [permissions].[permission_name] COLLATE DATABASE_DEFAULT + N' ON OBJECT::[bronze].[orders] FROM ' + QUOTENAME([principals].[name]) COLLATE DATABASE_DEFAULT + N';'), N' ')",
    "FROM sys.database_permissions AS [permissions]",
    "JOIN sys.database_principals AS [principals] ON [principals].[principal_id] = [permissions].[grantee_principal_id]",
    "JOIN sys.objects AS [objects] ON [objects].[object_id] = [permissions].[major_id]",
    "JOIN sys.schemas AS [schemas] ON [schemas].[schema_id] = [objects].[schema_id]",
    "WHERE [permissions].[class] = 1",
    "  AND [permissions].[minor_id] = 0",
    "  AND [permissions].[state] = 'G'",
    "  AND [schemas].[name] = N'bronze'",
    "  AND [objects].[name] = N'orders'",
    "  AND [permissions].[permission_name] NOT LIKE N'%[^A-Z ]%'",
    `  AND [principals].[name] <> USER_NAME()${kept ? "" : ";"}`,
    ...(kept
      ? [
          `  AND NOT ([permissions].[permission_name] = N'SELECT' AND [principals].[name] IN (${kept}));`,
        ]
      : []),
    "IF @revoke IS NOT NULL EXEC (@revoke);",
    "GO",
    "",
  ].join("\n");
}

/** Each diagnostic's code and message. */
export const diagnostics = (files: Record<string, string>) =>
  generate(files).result.diagnostics.map(({ code, message }) => ({ code, message }));

export const maskNotApplied =
  'The "hash" mask on "email" in table "orders" isn\'t applied on synapse: Synapse serverless has no data masking, and readers of views over files can read the files directly.';
